class Solution(object):
    def even_odd_palindrome(self, n):
        """
        :type n: int
        :rtype: List[int]
        """
        """
        Solution: 
            odd numbers have same structure with even numbers (one digit, two digits, ...).
            hence, only count the odd numbers.

            We keep track of the number of palindromes of length 1, length 2, ..., length 10.

            Here, I use a list comprehension to calculate the number of palindromes of a given length.
            It works as follows:

            - For lengths from 1 to 4 (which includes lengths of length 1, 2, 3, and 4),
                we directly add 9 (since there are 9 possible digit combinations for each of these lengths).
            - For lengths from 5 to 9 (which includes lengths of length 5, 6, 7, 8, and 9),
                we add 4 (since there are 4 possible digit combinations for each of these lengths).

            We also need to handle special cases:
            - For lengths of length 2, we need to consider the numbers that are multiples of 11 (e.g., 11, 22, 33, ..., 99).
            - For lengths of length 3, we need to consider the numbers that are multiples of 111 (e.g., 111, 222, 333, ..., 999).
            - For lengths of length 4, we need to consider the numbers that are multiples of 1111 (e.g., 1111, 2222, 3333, ..., 9999).

            Finally, we return the count of even and odd palindromes by filtering the list and summing the elements.
        """
        res = []
        even_count = 0
        odd_count = 0
        for i in range(1, n + 1):
            if i % 2 == 1:
                res.append(i)
                odd_count += 1
            if i == 2 or i == 4:
                even_count += 9
            elif i == 5:
                even_count += 4
            elif i == 7:
                even_count += 4
            elif i == 9:
                even_count += 4
            elif i >= 11:
                if i % 11 == 0:
                    even_count += 9
                else:
                    even_count += 4
            elif i >= 12:
                if i % 111 == 0:
                    even_count += 4
                else:
                    even_count += 4
            elif i >= 13:
                if i % 1111 == 0:
                    even_count += 4
                else:
                    even_count += 4
        return (even_count, odd_count)
